"""Static offline, searchable per-answer score viewer."""
import json
def render(out,rows,snapshot):
    data=json.dumps(dict(rows=rows,snapshot=snapshot),ensure_ascii=False).replace('<','\\u003c')
    template='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>第2章客观题实验</title>
<style>body{font:16px system-ui;margin:30px auto;max-width:1400px;color:#182334;background:#f5f7fa}h1{font-size:28px}table{border-collapse:collapse;width:100%;background:white}th,td{padding:9px;border-bottom:1px solid #dbe2ec;text-align:left}th{background:#eaf0f8}button,select,input{padding:9px;margin:5px}article{background:white;padding:20px;margin:15px 0;border-radius:10px}pre{white-space:pre-wrap;word-break:break-word}.muted{color:#56657a}summary{cursor:pointer}a{color:#1756a9}</style>
<h1>第2章客观题实验</h1><p><a href="../../results/index.html">开放问答结果</a> · <a href="summary.csv">汇总CSV</a> · <a href="per_answer.csv">逐答CSV</a> · <a href="snapshot.json">统计快照</a></p>
<p id="status"></p><p class="muted">题目经AI原文核验，未宣称独立人工审计通过。包含30组单选／判断跨题型配对；知识可与原开放题重叠。未完成配置不发布最终准确率。</p>
<div id="summary"></div><h2>逐题答案与评分</h2><div id="filters"></div><input id="query" placeholder="搜索题号或题目" size="45"><button id="previous">上一页</button><button id="next">下一页</button><span id="count"></span><div id="answers"></div>
<script>const DATA=__DATA__;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x==null?'待完成':(100*x).toFixed(2)+'%';
const s=DATA.snapshot;document.querySelector('#status').textContent=`任务完成 ${s.completed} / ${s.planned} · ${s.status==='closed'?'已闭合':'进行中'} · 更新 ${s.updated}`;
document.querySelector('#summary').innerHTML='<table><tr><th>模型／方法</th><th>终态</th><th>回答成功</th><th>正确</th><th>准确率</th><th>题型宏平均</th></tr>'+s.configurations.map(c=>`<tr><td>${esc(c.model)} / ${esc(c.method)}</td><td>${c.completed}/${c.planned}</td><td>${c.answered}</td><td>${c.correct}</td><td>${pct(c.accuracy)}</td><td>${pct(c.macro_accuracy)}</td></tr>`).join('')+'</table>';
for(const [key,label] of [['model','模型'],['method','方法'],['type','题型'],['reason','评分原因']]){const select=document.createElement('select');select.id=key;select.innerHTML=`<option value="">全部${label}</option>`+[...new Set(DATA.rows.map(r=>r[key]))].map(v=>`<option>${esc(v)}</option>`).join('');select.onchange=()=>{page=0;show()};document.querySelector('#filters').append(select)}
let page=0;function show(){let rows=DATA.rows.filter(r=>['model','method','type','reason'].every(k=>!document.getElementById(k).value||r[k]===document.getElementById(k).value));const q=document.querySelector('#query').value.toLowerCase();rows=rows.filter(r=>(r.id+' '+r.question).toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(rows.length/20)-1));document.querySelector('#count').textContent=`共${rows.length}条 · 第${page+1}页`;document.querySelector('#answers').innerHTML=rows.slice(page*20,(page+1)*20).map(r=>`<article><strong>${esc(r.id)} · ${esc(r.model)} / ${esc(r.method)} · ${r.score==null?'待运行':r.score+'分'} · ${esc(r.reason)}</strong><pre>${esc(r.question)}</pre><p>标准答案：${esc(r.expected)} ｜ 解析答案：${esc(r.normalized_answer)}</p><pre>${esc(r.raw_answer||'暂无回答')}</pre><details><summary>来源证据与运行信息</summary><pre>${esc(r.evidence)}\n状态：${esc(r.generation_status)}\n工具调用：${r.tools}；耗时：${r.seconds.toFixed(2)}s</pre></details></article>`).join('')};document.querySelector('#query').oninput=()=>{page=0;show()};document.querySelector('#previous').onclick=()=>{page--;show()};document.querySelector('#next').onclick=()=>{page++;show()};show();</script></html>'''
    (out/'results/index.html').write_text(template.replace('__DATA__',data),encoding='utf-8')
